package io.github.diodeme.ji.artifact.fs;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.ByteArrayInputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

final class HashingTest {
    @TempDir Path directory;

    @Test
    void rangedFileHashMatchesTheExactByteSlice() throws Exception {
        byte[] bytes = new byte[3 * 1024 * 1024 + 17];
        for (int index = 0; index < bytes.length; index++) bytes[index] = (byte) (index * 31);
        Path file = directory.resolve("artifact.bin");
        Files.write(file, bytes);
        int offset = 511_113;
        int length = 2 * 1024 * 1024 + 9;

        String ranged = Hashing.sha256Hex(file, offset, length);
        String expected = Hashing.sha256Hex(new ByteArrayInputStream(
                Arrays.copyOfRange(bytes, offset, offset + length)));

        assertEquals(expected, ranged);
    }
}
